import {
  OFFICIAL_FIXTURES_2026,
  OFFICIAL_ROUND_ONLY_2026,
  OFFICIAL_SOURCES_2026,
} from './officialFixtures2026.js';

const ROUND_ONLY = new Set(OFFICIAL_ROUND_ONLY_2026);

/**
 * The inaugural 2026/27 season uses the published fixture matrix, including
 * home/away order and available dates. Later seasons are generated by the game.
 *
 * Sources without a confirmed individual kickoff carry the official round date
 * at noon, explicitly marked as `official-round`, never a fabricated TV slot.
 */
export function buildOfficialSeason2026(leagueId, clubIds, getReferee = () => ({})) {
  const rows = OFFICIAL_FIXTURES_2026[leagueId];
  if (!rows) throw new Error(`No existe calendario 2026/27 para ${leagueId}`);

  const expected = new Set(clubIds);
  const fromSchedule = new Set(rows.flatMap(([, home, away]) => [home, away]));
  if (expected.size !== fromSchedule.size || [...expected].some(id => !fromSchedule.has(id)) ||
      rows.length !== expected.size * (expected.size - 1)) {
    throw new Error(`La plantilla de ${leagueId} no coincide con su calendario oficial 2026/27`);
  }

  const source = OFFICIAL_SOURCES_2026[leagueId];
  const roundOnly = ROUND_ONLY.has(leagueId);
  const fixtures = rows.map(([round, home, away, kickoffDate, kickoffTime]) => {
    const referee = getReferee();
    return {
      id: `fx_${round}_${home}_${away}`,
      matchday: round,
      homeClubId: home,
      awayClubId: away,
      kickoffDate,
      kickoffTime: roundOnly ? null : kickoffTime,
      homeGoals: null,
      awayGoals: null,
      played: false,
      events: [],
      substitutions: [],
      statsApplied: false,
      refereeName: referee?.name || 'Árbitro estándar',
      refereeStrictness: referee?.strictness ?? 1,
      meta: {
        official: true,
        source: 'official_2026_27',
        scheduleSource: source,
        schedulePrecision: roundOnly ? 'official-round' : kickoffTime ? 'official-kickoff' : 'official-date',
      },
    };
  });
  return { fixtures, maxMatchday: expected.size * 2 - 2 };
}
